// Package legal lists the third-party components compiled or bundled into
// vaquero, with their licences, for the open source notices page.
// third_party.json is generated by `go run ./scripts/notices` (part of
// make gen); never edit it by hand.
package legal

import (
	_ "embed"
	"encoding/json"
	"sync"
)

// Component is one third-party component and its licence text.
type Component struct {
	Name    string `json:"name"`
	Version string `json:"version,omitempty"`
	URL     string `json:"url,omitempty"`
	License string `json:"license"`
}

//go:embed third_party.json
var raw []byte

var parsed = sync.OnceValue(func() []Component {
	var cs []Component
	if err := json.Unmarshal(raw, &cs); err != nil {
		panic("legal: third_party.json: " + err.Error())
	}
	return cs
})

// ThirdParty is every third-party component, sorted by name.
func ThirdParty() []Component { return parsed() }
